//! Built-in sound effects and music loops, synthesised from scratch.
//!
//! Nothing here is sampled or copied: every sound is generated by small
//! oscillators, noise and envelopes, and every music loop is an original
//! progression and tune written in code. The output is released with the app
//! under CC0, so videos made with it can be published anywhere.
//!
//! Generation is deterministic (a fixed-seed noise generator), so the same
//! sound id always gives the same bytes. Sounds are returned as 16-bit mono
//! WAV files, ready to embed in a project like any imported sound.

use std::f32::consts::TAU;

/// One entry of the built-in sound library.
#[derive(Clone, Debug, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SoundInfo {
    pub id: &'static str,
    pub name: &'static str,
    /// "effect" or "music".
    pub kind: &'static str,
    pub category: &'static str,
    /// Length in seconds.
    pub secs: f32,
    /// Music loops play seamlessly when repeated.
    pub looped: bool,
}

const SFX_RATE: u32 = 44_100;
const MUSIC_RATE: u32 = 32_000;

macro_rules! fx {
    ($id:expr, $name:expr, $cat:expr, $secs:expr) => {
        SoundInfo { id: $id, name: $name, kind: "effect", category: $cat, secs: $secs, looped: false }
    };
}
macro_rules! mu {
    ($id:expr, $name:expr, $cat:expr, $secs:expr) => {
        SoundInfo { id: $id, name: $name, kind: "music", category: $cat, secs: $secs, looped: true }
    };
}

/// Every built-in sound.
pub fn catalog() -> Vec<SoundInfo> {
    vec![
        fx!("whoosh", "Whoosh", "Motion", 0.7),
        fx!("swoosh-up", "Swoosh up", "Motion", 0.6),
        fx!("swish", "Quick swish", "Motion", 0.3),
        fx!("slide-up", "Slide whistle up", "Motion", 0.8),
        fx!("slide-down", "Slide whistle down", "Motion", 0.8),
        fx!("pop", "Pop", "Cartoon", 0.18),
        fx!("bubble", "Bubble pops", "Cartoon", 0.6),
        fx!("boing", "Boing", "Cartoon", 0.8),
        fx!("bonk", "Bonk", "Cartoon", 0.4),
        fx!("punch", "Punch", "Cartoon", 0.35),
        fx!("ding", "Ding", "Alerts", 1.4),
        fx!("chime", "Success chime", "Alerts", 1.2),
        fx!("notify", "Notification", "Alerts", 0.5),
        fx!("buzz", "Wrong buzzer", "Alerts", 0.7),
        fx!("coin", "Coin", "Alerts", 0.5),
        fx!("sparkle", "Magic sparkle", "Alerts", 1.3),
        fx!("click", "Click", "Interface", 0.08),
        fx!("type", "Typing", "Interface", 1.2),
        fx!("shutter", "Camera shutter", "Interface", 0.35),
        fx!("glitch", "Glitch", "Interface", 0.5),
        fx!("boom", "Boom", "Drama", 1.6),
        fx!("rimshot", "Rimshot (joke)", "Drama", 1.0),
        fx!("riser", "Tension riser", "Drama", 2.0),
        fx!("heartbeat", "Heartbeat", "Drama", 1.7),
        fx!("applause", "Applause", "Crowd", 3.0),
        mu!("music-sunny", "Sunny Day", "Upbeat", 16.0),
        mu!("music-lofi", "Lo-fi Study", "Chill", 24.0),
        mu!("music-mystery", "Mystery Hall", "Suspense", 19.2),
        mu!("music-chip", "Tiny Adventure", "Playful", 13.71),
        mu!("music-news", "Breaking News", "Corporate", 16.0),
    ]
}

/// Generate a built-in sound as a WAV file (`None` for an unknown id).
pub fn render(id: &str) -> Option<Vec<u8>> {
    let (samples, rate) = match id {
        id if id.starts_with("music-") => (music(id)?, MUSIC_RATE),
        _ => (effect(id)?, SFX_RATE),
    };
    Some(wav(&samples, rate))
}

/// Media id of a built-in sound in a project.
pub fn media_id(sound: &str) -> String {
    format!("sound-{sound}")
}

/// A built-in sound as project media (WAV, measured at the project fps).
pub fn media(sound: &str, fps: u32) -> Option<crate::model::Media> {
    let info = catalog().into_iter().find(|s| s.id == sound)?;
    let bytes = render(sound)?;
    let (duration_frames, envelope) = crate::audio::analyse_wav(&bytes, fps).ok()?;
    Some(crate::model::Media {
        id: media_id(sound),
        name: info.name.to_string(),
        mime: "audio/wav".into(),
        data: base64(&bytes),
        duration_frames,
        envelope,
        source: Some(crate::model::MediaSource::File),
    })
}

/// Standard base64 (the project stores media this way).
pub fn base64(bytes: &[u8]) -> String {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for c in bytes.chunks(3) {
        let n = (c[0] as u32) << 16 | (*c.get(1).unwrap_or(&0) as u32) << 8 | *c.get(2).unwrap_or(&0) as u32;
        out.push(T[(n >> 18) as usize & 63] as char);
        out.push(T[(n >> 12) as usize & 63] as char);
        out.push(if c.len() > 1 { T[(n >> 6) as usize & 63] as char } else { '=' });
        out.push(if c.len() > 2 { T[n as usize & 63] as char } else { '=' });
    }
    out
}

/// Encode mono samples (-1..1) as a 16-bit PCM WAV.
pub fn wav(samples: &[f32], rate: u32) -> Vec<u8> {
    let n = samples.len() as u32;
    let mut out = Vec::with_capacity(44 + samples.len() * 2);
    out.extend_from_slice(b"RIFF");
    out.extend_from_slice(&(36 + n * 2).to_le_bytes());
    out.extend_from_slice(b"WAVEfmt ");
    out.extend_from_slice(&16u32.to_le_bytes());
    out.extend_from_slice(&1u16.to_le_bytes());
    out.extend_from_slice(&1u16.to_le_bytes());
    out.extend_from_slice(&rate.to_le_bytes());
    out.extend_from_slice(&(rate * 2).to_le_bytes());
    out.extend_from_slice(&2u16.to_le_bytes());
    out.extend_from_slice(&16u16.to_le_bytes());
    out.extend_from_slice(b"data");
    out.extend_from_slice(&(n * 2).to_le_bytes());
    for s in samples {
        out.extend_from_slice(&((s.clamp(-1.0, 1.0) * 32767.0) as i16).to_le_bytes());
    }
    out
}

// ------------------------------------------------------------------ building blocks

/// Deterministic white noise (xorshift).
struct Noise(u32);
impl Noise {
    fn new(seed: u32) -> Noise {
        Noise(seed.max(1))
    }
    fn next(&mut self) -> f32 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 17;
        x ^= x << 5;
        self.0 = x;
        (x as f32 / u32::MAX as f32) * 2.0 - 1.0
    }
}

/// One-pole low-pass filter.
#[derive(Default)]
struct Lp(f32);
impl Lp {
    fn run(&mut self, x: f32, cutoff: f32, rate: f32) -> f32 {
        let a = 1.0 - (-TAU * cutoff.max(10.0) / rate).exp();
        self.0 += a * (x - self.0);
        self.0
    }
}

/// Simple resonant state-variable band-pass, for noise sweeps.
#[derive(Default)]
struct Svf {
    low: f32,
    band: f32,
}
impl Svf {
    fn band(&mut self, x: f32, cutoff: f32, q: f32, rate: f32) -> f32 {
        let f = 2.0 * (std::f32::consts::PI * cutoff.min(rate * 0.2) / rate).sin();
        let high = x - self.low - q * self.band;
        self.band += f * high;
        self.low += f * self.band;
        self.band
    }
}

fn smooth(t: f32) -> f32 {
    let t = t.clamp(0.0, 1.0);
    t * t * (3.0 - 2.0 * t)
}

/// Attack / exponential decay envelope.
fn ad(t: f32, attack: f32, decay: f32) -> f32 {
    if t < 0.0 {
        0.0
    } else if t < attack {
        t / attack
    } else {
        (-(t - attack) / decay).exp()
    }
}

fn buf(secs: f32, rate: u32) -> Vec<f32> {
    vec![0.0; (secs * rate as f32) as usize]
}

/// Scale to a peak of `peak` and fade the last few ms to avoid clicks.
fn finish(mut v: Vec<f32>, peak: f32) -> Vec<f32> {
    let m = v.iter().fold(0.0f32, |a, s| a.max(s.abs())).max(1e-6);
    let k = peak / m;
    let n = v.len();
    let tail = (n / 50).clamp(1, 400);
    for (i, s) in v.iter_mut().enumerate() {
        *s *= k;
        if i + tail > n {
            *s *= (n - i) as f32 / tail as f32;
        }
    }
    v
}

/// A sine sweeping from `f0` to `f1` (exponentially) over the buffer.
fn sweep(out: &mut [f32], rate: f32, f0: f32, f1: f32, amp: impl Fn(f32) -> f32) {
    let n = out.len() as f32;
    let mut ph = 0.0f32;
    for (i, s) in out.iter_mut().enumerate() {
        let u = i as f32 / n;
        let f = f0 * (f1 / f0).powf(u);
        ph += f / rate;
        *s += (ph * TAU).sin() * amp(u);
    }
}

/// A bell-like tone: a few inharmonic partials with their own decays.
fn bell(out: &mut [f32], rate: f32, at: f32, f: f32, gain: f32, decay: f32) {
    let partials = [(1.0, 1.0, 1.0), (2.0, 0.5, 0.6), (2.76, 0.35, 0.4), (5.4, 0.2, 0.25), (8.9, 0.08, 0.15)];
    let start = (at * rate) as usize;
    for (i, s) in out.iter_mut().enumerate().skip(start) {
        let t = (i - start) as f32 / rate;
        let mut v = 0.0;
        for (m, a, d) in partials {
            v += (TAU * f * m * t).sin() * a * ad(t, 0.002, decay * d);
        }
        *s += v * gain;
    }
}

// ------------------------------------------------------------------ effects

fn effect(id: &str) -> Option<Vec<f32>> {
    let r = SFX_RATE as f32;
    let mut nz = Noise::new(0x9e37_79b9 ^ crate::geom::hash_str(id));
    let v = match id {
        "whoosh" | "swoosh-up" | "swish" => {
            let (secs, f0, f1) = match id {
                "whoosh" => (0.7, 300.0, 2600.0),
                "swoosh-up" => (0.6, 500.0, 5000.0),
                _ => (0.3, 900.0, 4200.0),
            };
            let mut v = buf(secs, SFX_RATE);
            let mut f = Svf::default();
            let n = v.len() as f32;
            for (i, s) in v.iter_mut().enumerate() {
                let u = i as f32 / n;
                // Rises then falls in pitch (whoosh) or keeps rising (up).
                let c = if id == "whoosh" { f0 + (f1 - f0) * (u * std::f32::consts::PI).sin() } else { f0 * (f1 / f0).powf(u) };
                let env = smooth(u * 2.5) * (1.0 - u).powf(1.3);
                *s = f.band(nz.next(), c, 0.6, r) * env;
            }
            finish(v, 0.8)
        }
        "slide-up" | "slide-down" => {
            let mut v = buf(0.8, SFX_RATE);
            let up = id == "slide-up";
            let n = v.len() as f32;
            let mut ph = 0.0f32;
            for (i, s) in v.iter_mut().enumerate() {
                let u = i as f32 / n;
                let k = if up { u } else { 1.0 - u };
                let f = 500.0 * 4.0f32.powf(k) * (1.0 + 0.012 * (TAU * 6.0 * u * 0.8).sin());
                ph += f / r;
                let env = smooth(u * 12.0) * smooth((1.0 - u) * 6.0);
                *s = ((ph * TAU).sin() + 0.08 * nz.next()) * env;
            }
            finish(v, 0.7)
        }
        "pop" => {
            let mut v = buf(0.18, SFX_RATE);
            sweep(&mut v, r, 900.0, 180.0, |u| ad(u, 0.01, 0.18));
            finish(v, 0.85)
        }
        "bubble" => {
            let mut v = buf(0.6, SFX_RATE);
            for (k, (at, f)) in [(0.0, 700.0), (0.13, 900.0), (0.24, 620.0), (0.38, 1100.0)].iter().enumerate() {
                let s0 = (*at * r) as usize;
                let len = (0.09 * r) as usize;
                let mut seg = vec![0.0; len];
                sweep(&mut seg, r, *f, f * 2.2, |u| ad(u, 0.05, 0.35));
                for (i, x) in seg.into_iter().enumerate() {
                    if let Some(s) = v.get_mut(s0 + i) {
                        *s += x * (1.0 - k as f32 * 0.12);
                    }
                }
            }
            finish(v, 0.75)
        }
        "boing" => {
            let mut v = buf(0.8, SFX_RATE);
            let n = v.len() as f32;
            let mut ph = 0.0f32;
            for (i, s) in v.iter_mut().enumerate() {
                let t = i as f32 / r;
                let u = i as f32 / n;
                let f = 160.0 + 130.0 * (TAU * 11.0 * t).sin() * (1.0 - u) + 80.0 * u;
                ph += f / r;
                let x = (ph * TAU).sin();
                *s = (x + 0.3 * (2.0 * x * x - 1.0)) * ad(t, 0.005, 0.35);
            }
            finish(v, 0.8)
        }
        "bonk" => {
            let mut v = buf(0.4, SFX_RATE);
            for (i, s) in v.iter_mut().enumerate() {
                let t = i as f32 / r;
                let f = 420.0 * (1.0 - 0.3 * (t / 0.4));
                *s = ((TAU * f * t).sin() + 0.5 * (TAU * f * 2.3 * t).sin() + 0.25 * (TAU * f * 3.9 * t).sin()) * ad(t, 0.001, 0.07)
                    + nz.next() * ad(t, 0.0005, 0.01) * 0.5;
            }
            finish(v, 0.85)
        }
        "punch" => {
            let mut v = buf(0.35, SFX_RATE);
            let mut lp = Lp::default();
            for (i, s) in v.iter_mut().enumerate() {
                let t = i as f32 / r;
                let body = (TAU * (110.0 - 60.0 * (t / 0.35)) * t).sin() * ad(t, 0.002, 0.08);
                let crack = lp.run(nz.next(), 2500.0, r) * ad(t, 0.0005, 0.03);
                *s = body + crack * 1.4;
            }
            finish(v, 0.9)
        }
        "ding" => {
            let mut v = buf(1.4, SFX_RATE);
            bell(&mut v, r, 0.0, 1318.5, 0.6, 0.9);
            finish(v, 0.7)
        }
        "chime" => {
            let mut v = buf(1.2, SFX_RATE);
            for (k, f) in [523.25, 659.25, 783.99, 1046.5].iter().enumerate() {
                bell(&mut v, r, k as f32 * 0.08, *f, 0.4, 0.6);
            }
            finish(v, 0.7)
        }
        "notify" => {
            let mut v = buf(0.5, SFX_RATE);
            for (at, f) in [(0.0, 880.0), (0.11, 1318.5)] {
                let s0 = (at * r) as usize;
                for (i, s) in v.iter_mut().enumerate().skip(s0) {
                    let t = (i - s0) as f32 / r;
                    *s += ((TAU * f * t).sin() + 0.2 * (TAU * f * 2.0 * t).sin()) * ad(t, 0.004, 0.12);
                }
            }
            finish(v, 0.7)
        }
        "buzz" => {
            let mut v = buf(0.7, SFX_RATE);
            let mut lp = Lp::default();
            for (i, s) in v.iter_mut().enumerate() {
                let t = i as f32 / r;
                let saw = |f: f32| 2.0 * (t * f).fract() - 1.0;
                let x = saw(110.0) + saw(116.5);
                let env = smooth(t * 60.0) * if t < 0.55 { 1.0 } else { smooth((0.7 - t) / 0.15) };
                *s = lp.run(x, 1800.0, r) * env;
            }
            finish(v, 0.6)
        }
        "coin" => {
            let mut v = buf(0.5, SFX_RATE);
            for (i, s) in v.iter_mut().enumerate() {
                let t = i as f32 / r;
                let f = if t < 0.07 { 987.8 } else { 1318.5 };
                let sq = if (t * f).fract() < 0.5 { 1.0 } else { -1.0 };
                *s = sq * 0.5 * if t < 0.07 { 1.0 } else { ad(t - 0.07, 0.001, 0.15) };
            }
            finish(v, 0.5)
        }
        "sparkle" => {
            let mut v = buf(1.3, SFX_RATE);
            let notes = [2093.0, 2637.0, 3136.0, 2349.0, 2793.0, 3520.0, 2637.0, 4186.0];
            for (k, f) in notes.iter().enumerate() {
                bell(&mut v, r, k as f32 * 0.07 + (nz.next() * 0.01), *f, 0.25, 0.35);
            }
            finish(v, 0.6)
        }
        "click" => {
            let mut v = buf(0.08, SFX_RATE);
            for (i, s) in v.iter_mut().enumerate() {
                let t = i as f32 / r;
                *s = (nz.next() * 0.6 + (TAU * 3200.0 * t).sin()) * ad(t, 0.0003, 0.006);
            }
            finish(v, 0.7)
        }
        "type" => {
            let mut v = buf(1.2, SFX_RATE);
            let mut at = 0.02f32;
            let mut k = 0;
            while at < 1.1 {
                let s0 = (at * r) as usize;
                let pitch = 1800.0 + 500.0 * ((k * 7 % 5) as f32);
                for (i, s) in v.iter_mut().enumerate().skip(s0).take((0.04 * r) as usize) {
                    let t = (i - s0) as f32 / r;
                    *s += (nz.next() * 0.7 + 0.5 * (TAU * pitch * t).sin()) * ad(t, 0.0003, 0.008);
                }
                at += 0.07 + 0.05 * ((k * 13 % 7) as f32 / 7.0);
                k += 1;
            }
            finish(v, 0.6)
        }
        "shutter" => {
            let mut v = buf(0.35, SFX_RATE);
            for at in [0.0f32, 0.12] {
                let s0 = (at * r) as usize;
                for (i, s) in v.iter_mut().enumerate().skip(s0) {
                    let t = (i - s0) as f32 / r;
                    *s += (nz.next() + 0.6 * (TAU * 2400.0 * t).sin()) * ad(t, 0.0005, 0.018);
                }
            }
            finish(v, 0.7)
        }
        "glitch" => {
            let mut v = buf(0.5, SFX_RATE);
            let n = v.len();
            let mut i = 0;
            let mut k = 0u32;
            while i < n {
                let len = ((0.015 + 0.03 * ((k * 5 % 4) as f32 / 4.0)) * r) as usize;
                let f = [220.0, 1760.0, 440.0, 3520.0, 110.0][(k % 5) as usize];
                let noisy = k % 3 == 1;
                for j in 0..len.min(n - i) {
                    let t = j as f32 / r;
                    v[i + j] = if noisy { nz.next() } else if (t * f).fract() < 0.5 { 0.8 } else { -0.8 };
                }
                i += len + if k % 4 == 3 { (0.02 * r) as usize } else { 0 };
                k += 1;
            }
            finish(v, 0.5)
        }
        "boom" => {
            let mut v = buf(1.6, SFX_RATE);
            let mut lp = Lp::default();
            for (i, s) in v.iter_mut().enumerate() {
                let t = i as f32 / r;
                let body = (TAU * (55.0 + 70.0 * (-t * 6.0).exp()) * t).sin() * ad(t, 0.003, 0.5);
                let rumble = lp.run(nz.next(), 300.0, r) * ad(t, 0.01, 0.6) * 3.0;
                *s = body + rumble;
            }
            finish(v, 0.95)
        }
        "rimshot" => {
            let mut v = buf(1.0, SFX_RATE);
            // ba-dum (two toms), then the cymbal.
            for (at, f) in [(0.0f32, 190.0f32), (0.16, 140.0)] {
                let s0 = (at * r) as usize;
                for (i, s) in v.iter_mut().enumerate().skip(s0).take((0.25 * r) as usize) {
                    let t = (i - s0) as f32 / r;
                    *s += (TAU * f * (1.0 - 0.3 * t) * t).sin() * ad(t, 0.001, 0.08) + nz.next() * ad(t, 0.0005, 0.01) * 0.4;
                }
            }
            let s0 = (0.42 * r) as usize;
            let mut hp_prev = 0.0;
            for (i, s) in v.iter_mut().enumerate().skip(s0) {
                let t = (i - s0) as f32 / r;
                let x = nz.next();
                let hp = x - hp_prev;
                hp_prev = x;
                *s += hp * ad(t, 0.001, 0.22) * 0.5;
            }
            finish(v, 0.85)
        }
        "riser" => {
            let mut v = buf(2.0, SFX_RATE);
            let mut f = Svf::default();
            let n = v.len() as f32;
            let mut ph = 0.0f32;
            for (i, s) in v.iter_mut().enumerate() {
                let u = i as f32 / n;
                let c = 300.0 * (8000.0f32 / 300.0).powf(u);
                ph += (110.0 * 8.0f32.powf(u)) / r;
                let tone = 2.0 * (ph).fract() - 1.0;
                *s = (f.band(nz.next(), c, 0.4, r) * 1.2 + tone * 0.25) * u.powf(1.6) * smooth((1.0 - u) * 40.0);
            }
            finish(v, 0.8)
        }
        "heartbeat" => {
            let mut v = buf(1.7, SFX_RATE);
            for at in [0.0f32, 0.22, 0.85, 1.07] {
                let s0 = (at * r) as usize;
                let soft = if at == 0.22 || at == 1.07 { 0.7 } else { 1.0 };
                for (i, s) in v.iter_mut().enumerate().skip(s0).take((0.3 * r) as usize) {
                    let t = (i - s0) as f32 / r;
                    *s += (TAU * (60.0 - 20.0 * t) * t).sin() * ad(t, 0.006, 0.07) * soft;
                }
            }
            finish(v, 0.95)
        }
        "applause" => {
            let mut v = buf(3.0, SFX_RATE);
            let n = v.len();
            // Many hands: short filtered noise bursts at pseudo-random times.
            let mut seed = Noise::new(77);
            for _ in 0..420 {
                let at = (seed.next() * 0.5 + 0.5) * 2.8;
                let s0 = (at * r) as usize;
                let c = 900.0 + 1500.0 * (seed.next() * 0.5 + 0.5);
                let mut f = Svf::default();
                for i in s0..(s0 + (0.03 * r) as usize).min(n) {
                    let t = (i - s0) as f32 / r;
                    v[i] += f.band(nz.next(), c, 0.9, r) * ad(t, 0.0008, 0.008);
                }
            }
            let nn = n as f32;
            for (i, s) in v.iter_mut().enumerate() {
                let u = i as f32 / nn;
                *s *= smooth(u * 8.0) * smooth((1.0 - u) * 2.5);
            }
            finish(v, 0.7)
        }
        _ => return None,
    };
    Some(v)
}

// ------------------------------------------------------------------ music

/// Note number (MIDI) to frequency.
fn hz(n: f32) -> f32 {
    440.0 * 2.0f32.powf((n - 69.0) / 12.0)
}

/// Voices a tune can use.
#[derive(Clone, Copy)]
enum Inst {
    /// Soft electric piano (sine with a bell overtone).
    Keys,
    /// Plucked string (Karplus-Strong).
    Pluck,
    /// Round sine bass.
    Bass,
    /// Square-wave chip lead.
    Chip,
    /// Slow pad (detuned saws, low-passed).
    Pad,
    /// Short bright synth stab.
    Stab,
}

/// A note: start beat, length in beats, MIDI note, volume.
type Note = (f32, f32, f32, f32);

struct Song {
    bpm: f32,
    beats: f32,
    swing: f32,
    parts: Vec<(Inst, Vec<Note>)>,
    /// Drum pattern per bar (16 steps): kick, snare, hat strings ("x" = hit).
    drums: Option<[&'static str; 3]>,
    drum_gain: f32,
    vinyl: bool,
}

fn add_note(out: &mut [f32], rate: f32, inst: Inst, start: f32, len: f32, note: f32, vol: f32, seed: u32) {
    let f = hz(note);
    let s0 = (start * rate) as usize;
    let tail = match inst {
        Inst::Pad => 1.2,
        Inst::Pluck | Inst::Keys => 1.0,
        _ => 0.25,
    };
    let total = ((len + tail) * rate) as usize;
    let n = out.len();
    match inst {
        Inst::Pluck => {
            // Karplus-Strong: a noise burst through a delay line that averages.
            let period = (rate / f).max(2.0) as usize;
            let mut nz = Noise::new(seed);
            let mut line: Vec<f32> = (0..period).map(|_| nz.next()).collect();
            let mut idx = 0;
            for i in 0..total {
                let next = (idx + 1) % period;
                let v = line[idx];
                line[idx] = 0.5 * (v + line[next]) * 0.996;
                idx = next;
                let t = i as f32 / rate;
                let gate = if t > len { (-(t - len) / 0.08).exp() } else { 1.0 };
                out[(s0 + i) % n] += v * vol * 0.8 * gate;
            }
        }
        _ => {
            let mut lp = Lp::default();
            for i in 0..total {
                let t = i as f32 / rate;
                let rel = |r: f32| if t > len { (-(t - len) / r).exp() } else { 1.0 };
                let v = match inst {
                    Inst::Keys => ((TAU * f * t).sin() + 0.25 * (TAU * f * 2.0 * t).sin() * (-t * 6.0).exp() + 0.12 * (TAU * f * 3.0 * t).sin()) * ad(t, 0.004, 0.9) * rel(0.25),
                    Inst::Bass => {
                        let x = (TAU * f * t).sin();
                        (x + 0.15 * (TAU * f * 2.0 * t).sin()) * smooth(t * 120.0) * rel(0.06)
                    }
                    Inst::Chip => {
                        let duty = if (f * t).fract() < 0.5 { 1.0 } else { -1.0 };
                        let vib = 1.0 + 0.004 * (TAU * 5.5 * t).sin() * smooth((t - 0.15) * 4.0);
                        let d2 = if (f * vib * t).fract() < 0.25 { 1.0 } else { -1.0 };
                        (duty * 0.3 + d2 * 0.7) * 0.4 * smooth(t * 200.0) * rel(0.04) * (1.0 - 0.3 * smooth(t / len.max(0.01)))
                    }
                    Inst::Pad => {
                        let saw = |k: f32| 2.0 * (f * k * t).fract() - 1.0;
                        let x = (saw(1.0) + saw(1.006) + saw(0.994)) / 3.0;
                        lp.run(x, 900.0, rate) * smooth(t / 0.35) * rel(0.6)
                    }
                    Inst::Stab => {
                        let saw = |k: f32| 2.0 * (f * k * t).fract() - 1.0;
                        lp.run((saw(1.0) + saw(1.01)) * 0.5, 600.0 + 3000.0 * (-t * 18.0).exp(), rate) * ad(t, 0.002, 0.14) * rel(0.05)
                    }
                    Inst::Pluck => 0.0,
                };
                out[(s0 + i) % n] += v * vol;
            }
        }
    }
}

fn add_drum(out: &mut [f32], rate: f32, kind: u8, at: f32, gain: f32, nz: &mut Noise) {
    let s0 = (at * rate) as usize;
    let n = out.len();
    let len = (0.35 * rate) as usize;
    let mut prev = 0.0;
    for i in 0..len {
        let t = i as f32 / rate;
        let v = match kind {
            0 => (TAU * (48.0 + 90.0 * (-t * 30.0).exp()) * t).sin() * ad(t, 0.001, 0.16),
            1 => nz.next() * ad(t, 0.001, 0.09) * 0.6 + (TAU * 190.0 * t).sin() * ad(t, 0.001, 0.05) * 0.5,
            _ => {
                let x = nz.next();
                let hp = x - prev;
                prev = x;
                hp * ad(t, 0.0005, 0.025) * 0.35
            }
        };
        out[(s0 + i) % n] += v * gain;
    }
}

/// Chord tones (MIDI) for a root and quality, used to write accompaniments.
fn chord(root: f32, minor: bool, seventh: bool) -> Vec<f32> {
    let mut v = vec![root, root + if minor { 3.0 } else { 4.0 }, root + 7.0];
    if seventh {
        v.push(root + if minor { 10.0 } else { 11.0 });
    }
    v
}

/// Repeat a list of notes `times` times, `every` beats apart.
fn repeat(notes: &[Note], times: usize, every: f32) -> Vec<Note> {
    (0..times).flat_map(|k| notes.iter().map(move |&(b, l, n, v)| (b + k as f32 * every, l, n, v))).collect()
}

fn song(id: &str) -> Option<Song> {
    Some(match id {
        // Bright pop: I-V-vi-IV in C, plucky keys, bouncy bass, a whistle-like lead.
        "music-sunny" => {
            let prog = [(60.0, false), (67.0, false), (69.0, true), (65.0, false)];
            let mut keys = vec![];
            let mut bass = vec![];
            for (bar, &(root, minor)) in prog.iter().cycle().take(8).enumerate() {
                let b = bar as f32 * 4.0;
                for (k, off) in [0.0, 1.5, 2.5, 3.5].iter().enumerate() {
                    for n in chord(root, minor, false) {
                        keys.push((b + off, if k == 0 { 1.2 } else { 0.6 }, n, 0.09));
                    }
                }
                let r = root - 24.0;
                for (off, n) in [(0.0, r), (1.0, r), (1.5, r + 12.0), (2.0, r), (3.0, r + 7.0), (3.5, r + 12.0)] {
                    bass.push((b + off, 0.4, n, 0.32));
                }
            }
            let lead = [
                (0.0, 0.5, 76.0), (0.5, 0.5, 79.0), (1.0, 1.0, 81.0), (2.0, 0.5, 79.0), (2.5, 1.5, 76.0),
                (4.0, 0.5, 74.0), (4.5, 0.5, 76.0), (5.0, 1.0, 79.0), (6.0, 2.0, 74.0),
                (8.0, 0.5, 72.0), (8.5, 0.5, 74.0), (9.0, 1.0, 76.0), (10.0, 0.5, 79.0), (10.5, 1.5, 81.0),
                (12.0, 1.0, 79.0), (13.0, 1.0, 77.0), (14.0, 2.0, 76.0),
            ];
            let lead: Vec<Note> = lead.iter().map(|&(b, l, n)| (b + 16.0, l, n, 0.16)).collect();
            Song {
                bpm: 120.0,
                beats: 32.0,
                swing: 0.0,
                parts: vec![(Inst::Pluck, keys), (Inst::Bass, bass), (Inst::Keys, lead)],
                drums: Some(["x.....x.x.......", "....x.......x...", "x.x.x.x.x.x.x.xx"]),
                drum_gain: 0.5,
                vinyl: false,
            }
        }
        // Lo-fi: lazy swung beat, jazzy seventh chords, warm keys, vinyl hiss.
        "music-lofi" => {
            let prog = [(62.0, true), (67.0, false), (60.0, false), (57.0, true)];
            let mut keys = vec![];
            let mut bass = vec![];
            for (bar, &(root, minor)) in prog.iter().cycle().take(8).enumerate() {
                let b = bar as f32 * 4.0;
                for n in chord(root, minor, true) {
                    keys.push((b, 1.8, n, 0.08));
                    keys.push((b + 2.5, 1.2, n, 0.06));
                }
                bass.push((b, 1.5, root - 24.0, 0.35));
                bass.push((b + 2.5, 1.0, root - 24.0 + 7.0, 0.3));
            }
            let lead = repeat(&[(0.5, 0.5, 74.0, 0.07), (1.5, 0.5, 72.0, 0.06), (3.0, 1.0, 69.0, 0.07), (6.5, 0.5, 71.0, 0.06), (7.0, 1.0, 67.0, 0.06)], 4, 8.0);
            Song {
                bpm: 80.0,
                beats: 32.0,
                swing: 0.18,
                parts: vec![(Inst::Keys, keys), (Inst::Bass, bass), (Inst::Pluck, lead)],
                drums: Some(["x.......x.x.....", "....x.......x...", "x.x.x.x.x.x.x.x."]),
                drum_gain: 0.45,
                vinyl: true,
            }
        }
        // Suspense: minor pad, ticking plucks, a low pulse; no drums.
        "music-mystery" => {
            let prog = [(57.0, true), (53.0, false), (55.0, false), (52.0, false)];
            let mut pad = vec![];
            let mut pulse = vec![];
            let mut ticks = vec![];
            for (bar, &(root, minor)) in prog.iter().cycle().take(8).enumerate() {
                let b = bar as f32 * 4.0;
                for n in chord(root - 12.0, minor, false) {
                    pad.push((b, 3.8, n, 0.07));
                }
                for k in 0..4 {
                    pulse.push((b + k as f32, 0.5, root - 24.0, 0.3));
                }
            }
            let motif = [69.0, 72.0, 76.0, 75.0, 72.0, 69.0, 68.0, 71.0];
            for k in 0..32 {
                ticks.push((k as f32 * 1.0 + 0.5, 0.25, motif[k % 8] + 12.0, 0.05 + 0.03 * ((k % 4 == 0) as u8 as f32)));
            }
            Song { bpm: 100.0, beats: 32.0, swing: 0.0, parts: vec![(Inst::Pad, pad), (Inst::Bass, pulse), (Inst::Pluck, ticks)], drums: None, drum_gain: 0.0, vinyl: false }
        }
        // Chiptune: square lead and arpeggios, fast and cheerful.
        "music-chip" => {
            let prog = [(60.0, false), (65.0, false), (67.0, false), (60.0, false)];
            let mut arp = vec![];
            let mut bass = vec![];
            for (bar, &(root, minor)) in prog.iter().cycle().take(8).enumerate() {
                let b = bar as f32 * 4.0;
                let c = chord(root + 12.0, minor, false);
                for k in 0..16 {
                    arp.push((b + k as f32 * 0.25, 0.2, c[k % 3], 0.05));
                }
                for k in 0..4 {
                    bass.push((b + k as f32, 0.45, root - 12.0 + if k % 2 == 1 { 7.0 } else { 0.0 }, 0.14));
                }
            }
            let tune = [
                (0.0, 1.0, 72.0), (1.0, 0.5, 76.0), (1.5, 0.5, 79.0), (2.0, 1.0, 84.0), (3.0, 1.0, 79.0),
                (4.0, 1.5, 81.0), (5.5, 0.5, 77.0), (6.0, 2.0, 81.0),
                (8.0, 1.0, 79.0), (9.0, 0.5, 83.0), (9.5, 0.5, 79.0), (10.0, 1.0, 74.0), (11.0, 1.0, 77.0),
                (12.0, 3.0, 76.0), (15.0, 1.0, 72.0),
            ];
            let lead: Vec<Note> = repeat(&tune.iter().map(|&(b, l, n)| (b, l, n, 0.12)).collect::<Vec<_>>(), 2, 16.0);
            Song {
                bpm: 140.0,
                beats: 32.0,
                swing: 0.0,
                parts: vec![(Inst::Chip, arp), (Inst::Chip, bass), (Inst::Chip, lead)],
                drums: Some(["x.......x.......", "....x.......x...", "..x...x...x...x."]),
                drum_gain: 0.35,
                vinyl: false,
            }
        }
        // News bed: driving stabs and pulses in a serious minor key.
        "music-news" => {
            let prog = [(57.0, true), (57.0, true), (53.0, false), (55.0, false)];
            let mut stabs = vec![];
            let mut bass = vec![];
            let mut pad = vec![];
            for (bar, &(root, minor)) in prog.iter().cycle().take(8).enumerate() {
                let b = bar as f32 * 4.0;
                for off in [0.0, 0.75, 1.5, 2.5, 3.0] {
                    for n in chord(root, minor, false) {
                        stabs.push((b + off, 0.2, n, 0.07));
                    }
                }
                for k in 0..8 {
                    bass.push((b + k as f32 * 0.5, 0.3, root - 24.0, 0.26));
                }
                for n in chord(root + 12.0, minor, false) {
                    pad.push((b, 3.9, n, 0.03));
                }
            }
            Song {
                bpm: 120.0,
                beats: 32.0,
                swing: 0.0,
                parts: vec![(Inst::Stab, stabs), (Inst::Bass, bass), (Inst::Pad, pad)],
                drums: Some(["x.....x...x.....", "....x.......x...", "xxxxxxxxxxxxxxxx"]),
                drum_gain: 0.4,
                vinyl: false,
            }
        }
        _ => return None,
    })
}

fn music(id: &str) -> Option<Vec<f32>> {
    let s = song(id)?;
    let rate = MUSIC_RATE as f32;
    let spb = 60.0 / s.bpm;
    // The buffer is exactly the loop: notes ringing past the end wrap around
    // to the start, so the loop repeats without a seam.
    let mut out = vec![0.0f32; (s.beats * spb * rate) as usize];
    let swing = |beat: f32| {
        // Push off-beat eighths later.
        if (beat * 2.0).fract().abs() < 1e-3 && (beat * 2.0) as i32 % 2 == 1 {
            beat + s.swing * 0.5
        } else {
            beat
        }
    };
    for (pi, (inst, notes)) in s.parts.iter().enumerate() {
        for (k, &(b, l, n, v)) in notes.iter().enumerate() {
            add_note(&mut out, rate, *inst, swing(b) * spb, l * spb, n, v, (pi * 1000 + k) as u32 + 1);
        }
    }
    if let Some(d) = s.drums {
        let mut nz = Noise::new(4242);
        let bars = (s.beats / 4.0) as usize;
        for bar in 0..bars {
            for (kind, pat) in d.iter().enumerate() {
                for (step, ch) in pat.chars().enumerate() {
                    if ch == 'x' {
                        let beat = bar as f32 * 4.0 + step as f32 * 0.25;
                        let g = s.drum_gain * if kind == 2 && step % 2 == 1 { 0.7 } else { 1.0 };
                        add_drum(&mut out, rate, kind as u8, swing(beat) * spb, g, &mut nz);
                    }
                }
            }
        }
    }
    if s.vinyl {
        let mut nz = Noise::new(99);
        let mut lp = Lp::default();
        for s in out.iter_mut() {
            let crackle = if nz.next() > 0.9993 { nz.next() * 0.4 } else { 0.0 };
            *s += lp.run(nz.next(), 3000.0, rate) * 0.012 + crackle;
        }
        // Warm it up: a gentle low-pass over the whole mix.
        let mut lp = Lp::default();
        for s in out.iter_mut() {
            *s = lp.run(*s, 5200.0, rate);
        }
    }
    // Soft-clip and normalise.
    let peak = out.iter().fold(0.0f32, |a, s| a.max(s.abs())).max(1e-6);
    Some(out.into_iter().map(|s| (s / peak * 1.3).tanh() * 0.8).collect())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_sound_renders() {
        for s in catalog() {
            let w = render(s.id).unwrap_or_else(|| panic!("{} missing", s.id));
            let rate = if s.kind == "music" { MUSIC_RATE } else { SFX_RATE };
            let secs = (w.len() - 44) as f32 / 2.0 / rate as f32;
            assert!((secs - s.secs).abs() < 0.05, "{}: {secs}s, catalogue says {}", s.id, s.secs);
            let (samples, _) = crate::audio::wav_mono(&w).unwrap();
            let peak = samples.iter().fold(0.0f32, |a, x| a.max(x.abs()));
            assert!(peak > 0.2, "{} is silent", s.id);
        }
        assert_eq!(render("music-sunny"), render("music-sunny"), "deterministic");
    }
}
